INSERT {
  <http://data.semanticweb.org/person/edwin-bonilla> <http://www.example.org/test> ?newX .
} WHERE {
  {
    SELECT (MAX(?x) as ?maxX) WHERE {
      OPTIONAL { <http://data.semanticweb.org/person/edwin-bonilla> <http://www.example.org/test> ?x . }
    }
  }

  BIND(IF(BOUND(?maxX), ?maxX + 1, 0) AS ?newX) .
}

